# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_labels([Span(544, 1034)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_halves_round_up(self):
        result = round_labels([Span(68, 128)], 15)
        self.assertEqual(result, ["01:15-02:15 (1h 0m)"])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
